#include <vector>
#include <string>
#include <unordered_set>
#include <numeric>

class Solution {
public:
    int numSimilarGroups(std::vector<std::string>& strs) {
        int n = strs.size();
        std::vector<int> parent(n);
        std::iota(parent.begin(), parent.end(), 0);

        auto find = [&](auto self, int i) -> int {
            return parent[i] == i ? i : parent[i] = self(self, parent[i]);
        };

        auto isSimilar = [&](const std::string& a, const std::string& b) {
            int diff = 0;
            for (size_t i = 0; i < a.size(); ++i) {
                if (a[i] != b[i]) {
                    diff++;
                    if (diff > 2) return false;
                }
            }
            return diff == 0 || diff == 2;
        };

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (isSimilar(strs[i], strs[j])) {
                    int pi = find(find, i);
                    int pj = find(find, j);
                    if (pi != pj) parent[pi] = pj;
                }
            }
        }

        std::unordered_set<int> roots;
        for (int i = 0; i < n; ++i) roots.insert(find(find, i));
        return roots.size();
    }
};

import java.util.*;

class Solution {
    public int numSimilarGroups(String[] strs) {
        int n = strs.length;
        int[] parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (isSimilar(strs[i], strs[j])) {
                    int pi = find(i, parent);
                    int pj = find(j, parent);
                    if (pi != pj) parent[pi] = pj;
                }
            }
        }
        Set<Integer> roots = new HashSet<>();
        for (int i = 0; i < n; i++) roots.add(find(i, parent));
        return roots.size();
    }

    private int find(int i, int[] parent) {
        return parent[i] == i ? i : (parent[i] = find(parent[i], parent));
    }

    private boolean isSimilar(String a, String b) {
        int diff = 0;
        for (int i = 0; i < a.length(); i++) {
            if (a.charAt(i) != b.charAt(i)) {
                diff++;
                if (diff > 2) return false;
            }
        }
        return diff == 0 || diff == 2;
    }
}

